mapper.select:
select 1
from comment_reply
where id = #{replyId}
  and post_id = #{postId}
  and root_comment_id = #{commentId}
  and status = 1
    limit 1

mapper.update:
update comment_reply
set status = 0,
    updated_at = now()
where id = #{replyId}
  and user_uuid = #{currUserUuid}
  and status = 1
